 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.makeInputFromParent();
        for (let i = 1; i < 13; i++) {
            $("#isu_dd" + i).datepicker(myDateOpts);
            $("#redmpt_dd" + i).datepicker(myDateOpts);
        }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf10001.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

