/**
 * @method
 * @name isu_check
 * @description isu check 처리
 * @param {*} fm fm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.isu_check = async function (fm) {
    fm = (document.InputForm || { elements: [] });
    let nullChk = 'OK';
    let temp;
    let korIsuNmCheck = false;
    isu_nm_b = new Array(12);
    isu_nm_u = new Array(12);
    eng_isu_nm_b = new Array(12);
    eng_isu_nm_u = new Array(12);
    iss_amt = new Array(12);
    iss_dt = new Array(12);
    rdmp_dt = new Array(12);
    for (idx = 1; idx < 13; idx++) {
        isu_nm_b[idx] = fm["appl_isu_nm_b"+idx].value;
        isu_nm_u[idx] = fm["appl_isu_nm_u"+idx].value;
        eng_isu_nm_b[idx] = fm["appl_isu_eng_nm_b"+idx].value;
        eng_isu_nm_u[idx] = fm["appl_isu_eng_nm_u"+idx].value;
        iss_amt[idx] = fm["isu_schdl_amt"+idx].value;
        iss_dt[idx] = fm["isu_dd"+idx].value;
        rdmp_dt[idx] = fm["redmpt_dd"+idx].value;
        if ($c.str.getByteLength(isu_nm_b[idx]) > 0) {
            if ($c.str.getByteLength(isu_nm_u[idx]) === 0) {
