/**
 * @method
 * @name setIsuNmInput
 * @description set Isu Nm Input 처리
 * @param {*} fm fm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setIsuNmInput = async function (fm) {
    fm = (document.InputForm || { elements: [] });
    if ($c.str.getByteLength($c.util.getComponent('ipt_isuYyyy').getValue()) !== 4) {
        await $c.win.alert('발행연도를 입력하십시요.');
        $c.util.getComponent("ipt_isuYyyy").focus();
        return;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_isuMm').getValue()) === 0) {
        await $c.win.alert("발행월을 입력해주십시오.");
        $c.util.getComponent("ipt_isuMm").focus();
        return;
    }
    if (parseInt($c.util.getComponent('ipt_isuMm').getValue()) > 12) {
        await $c.win.alert("입력한 발행월의 형식이 올바르지 않습니다.");
        $c.util.getComponent("ipt_isuMm").focus();
        return;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_korIsuNm').getValue()) === 0) {
        await $c.win.alert("한글종목명을 입력해주십시오.");
        $c.util.getComponent("ipt_korIsuNm").focus();
        return;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_engIsuNm').getValue()) === 0) {
        await $c.win.alert("영문종목명을 입력해주십시오.");
        $c.util.getComponent("ipt_engIsuNm").focus();
        return;
    }
    const krCheck = false;
    const engCheck = false;
    const isu_mm = $c.util.getComponent('ipt_isuMm').getValue().replace(/0/gi, "");
    for (idx = 1; idx < 13; idx++) {
        for (idx1 = isu_mm; idx1 < 13; idx1++) {
            fm["appl_isu_nm_b"+idx1].value = $c.util.getComponent('ipt_korIsuNm').getValue();
        }
        for (idx2 = isu_mm; idx2 < 13; idx2++) {
            fm["appl_isu_eng_nm_b"+idx2].value = $c.util.getComponent('ipt_engIsuNm').getValue();
        }
    }
};

/**
