        }
        if ($c.str.getByteLength(fm["appl_isu_eng_nm_b"+idx].value) > 0) {
            fm["appl_isu_eng_nm_u"+idx].value = nowYear + '-' + ((idx > 9) ? idx : '0' + idx);
