/**
 * @method
 * @name isYunMonth
 * @description is Yun Month 처리
 * @param {*} strYear strYear
 * @returns {void}
 * @hidden N
 */
scwin.isYunMonth = function (strYear) {
    nYear = parseInt(strYear);
    if ((nYear % 4) === 0) {
        return true;
    } else {
        return false;
    }
};

/**
 * @method
 * @name setIssExprDDInput
 * @description set Iss Expr DDInput 처리
 * @param {*} fm fm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setIssExprDDInput = async function (fm) {
    fm = (document.InputForm || { elements: [] });
    if ($c.str.getByteLength($c.util.getComponent('ipt_isuYyyy').getValue()) !== 4) {
        await $c.win.alert('발행연도를 입력하십시요.');
        $c.util.getComponent("ipt_isuYyyy").focus();
        return;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_isuMm').getValue()) < 1) {
        await $c.win.alert("발행월을 입력해주십시오.");
        $c.util.getComponent("ipt_isuMm").focus();
        return;
    }
    if (parseInt($c.util.getComponent('ipt_isuMm').getValue()) > 12) {
        await $c.win.alert("입력한 발행월의 형식이 올바르지 않습니다.");
        $c.util.getComponent("ipt_isuMm").focus();
        return;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_bndExprTerm').getValue()) < 1) {
        await $c.win.alert('채권만기 기간을 입력하십시요.');
        $c.util.getComponent("ipt_bndExprTerm").focus();
        return;
    }
    nExprYy = parseInt($c.util.getComponent('ipt_isuYyyy').getValue(), 10) + parseInt($c.util.getComponent('ipt_bndExprTerm').getValue(), 10);
    mmCnt = new Array(12);
    mmCnt[1] = '31';
    mmCnt[3] = '31';
    mmCnt[4] = '30';
    mmCnt[5] = '31';
    mmCnt[6] = '30';
    mmCnt[7] = '31';
    mmCnt[8] = '31';
    mmCnt[9] = '30';
    mmCnt[10] = '31';
    mmCnt[11] = '30';
    mmCnt[12] = '31';
    if (scwin.isYunMonth($c.util.getComponent('ipt_isuYyyy').getValue())) {
        mmCnt[2] = '29';
    } else {
        mmCnt[2] = '28';
    }
    for (idx = 1; idx < 13; idx++) {
        if ($c.str.getByteLength(fm["appl_isu_nm_b"+idx].value) > 0) {
            fm["isu_dd"+idx].value = $c.util.getComponent('ipt_isuYyyy').getValue()+ "-" + ((idx > 9) ? idx : '0' + idx) + "-" + mmCnt[idx];
            if (idx === 2) {
                if (scwin.isYunMonth(nExprYy)) {
                    fm["redmpt_dd"+idx].value = nExprYy + "-" + ((idx > 9) ? '' + idx : '0' + idx) + "-" + '29';
                } else {
                    fm["redmpt_dd"+idx].value = nExprYy + "-" + ((idx > 9) ? '' + idx : '0' + idx) + "-" + '28';
                }
            } else {
                fm["redmpt_dd"+idx].value = nExprYy + "-" + ((idx > 9) ? '' + idx : '0' + idx) + "-" + mmCnt[idx];
            }
        }
    }
};

/**
 * @method
 * @name setIssAmtInput
 * @description set Iss Amt Input 처리
 * @param {*} fm fm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setIssAmtInput = async function (fm) {
    fm = (document.InputForm || { elements: [] });
    const amtCheck = false;
    let strDayAmt = '';
    if ($c.str.getByteLength($c.util.getComponent('ipt_dayIsuAmt').getValue()) < 1) {
        await $c.win.alert('일발행금액을 입력해주십시오.');
        $c.util.getComponent("ipt_dayIsuAmt").focus();
        return;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_multifly').getValue()) < 1) {
        await $c.win.alert('배수를 입력해주십시오.');
        $c.util.getComponent("ipt_multifly").focus();
        return;
    }
    nExprYy = parseInt($c.util.getComponent('ipt_multifly').getValue(), 10);
    for (idx = 1; idx < 13; idx++) {
        if ($c.str.getByteLength(fm["appl_isu_nm_b"+idx].value) > 0) {
            strDayAmt = Del_MoneyComma_Value($c.util.getComponent('ipt_dayIsuAmt').getValue());
            fm["isu_schdl_amt"+idx].value = (parseInt(strDayAmt, 10) * nExprYy) + '';
        }
    }
    for (let i = 1; i < 13; i++) {
        fm["isu_schdl_amt"+i].value = $c.num.formatMoney(fm["isu_schdl_amt"+i].value);
    }
};

/**
 * @method
 * @name fnCheckCurrentTime
 * @description fn Check Current Time 처리
 * @param {Object} obj 컴포넌트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnCheckCurrentTime = async function (obj) {
    const d = new Date();
    if ((obj.getValue() == null ? '' : String(obj.getValue())) !== '' && parseInt(obj.getValue()) < d.getFullYear()) {
        await $c.win.alert('발행연도는 ' + d.getFullYear() + '연도 부터 입력 가능합니다.');
        obj.setValue('');
        (obj && obj.setFocus ? obj.setFocus() : (obj && obj.focus ? obj.focus() : void 0));
        return;
    }
};
